{
  "name": "Paper Composer",
  "description": "Transform handwritten notes and exam papers into professionally formatted, print-ready A4 digital documents using AI-powered OCR and formatting.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ExamPaperData {
  title: string;
  subject: string;
  totalMarks: string;
  timeAllowed: string;
  sections: ExamSection[];
}

export interface ExamSection {
  title: string;
  instructions?: string;
  questions: ExamQuestion[];
}

export interface ExamQuestion {
  id: string;
  number: string;
  text: string;
  marks?: string;
  subQuestions?: string[];
}

export enum AppState {
  LANDING = 'LANDING',
  UPLOAD = 'UPLOAD',
  PROCESSING = 'PROCESSING',
  EDITOR = 'EDITOR'
}

export interface UploadedFile {
  file: File;
  preview: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const PROMPT_SYSTEM = `You are an expert exam paper composer. 
Your task is to take images of handwritten exam papers or notes and convert them into a structured, professional digital format.
Clean up the text, fix spelling errors, and identify logical sections like Header Information (School name, Subject, Marks), Sections (Section A, B, etc.), and Questions.
Maintain the original numbering and hierarchy.
If you see mathematical symbols or equations, format them clearly.
Output the data in a structured JSON format following the provided schema.`;

const EXAM_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING, description: 'The main title or school name if present' },
    subject: { type: Type.STRING, description: 'The subject of the exam' },
    totalMarks: { type: Type.STRING, description: 'Total marks for the paper' },
    timeAllowed: { type: Type.STRING, description: 'Time limit' },
    sections: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: 'Section title (e.g., Section A: MCQs)' },
          instructions: { type: Type.STRING, description: 'Special instructions for this section' },
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                number: { type: Type.STRING, description: 'Question number' },
                text: { type: Type.STRING, description: 'Main question text' },
                marks: { type: Type.STRING, description: 'Marks assigned to this question' },
                subQuestions: {
                  type: Type.ARRAY,
                  items: { type: Type.STRING }
                }
              },
              required: ['number', 'text']
            }
          }
        },
        required: ['title', 'questions']
      }
    }
  },
  required: ['title', 'subject', 'sections']
};

export const processHandwrittenImage = async (base64Images: string[]): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts = base64Images.map(img => ({
    inlineData: {
      data: img.split(',')[1],
      mimeType: 'image/jpeg'
    }
  }));

  parts.push({ text: "Please transcribe and format this handwritten exam paper into a professional digital structure." } as any);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: parts as any },
      config: {
        systemInstruction: PROMPT_SYSTEM,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
      }
    });

    if (!response.text) {
      throw new Error("No content generated");
    }

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

