import React from 'react';
import { ExamPaperData, ExamSection, ExamQuestion } from '../types';

interface EditorSectionProps {
  data: ExamPaperData;
  onChange: (newData: ExamPaperData) => void;
}

const EditorSection: React.FC<EditorSectionProps> = ({ data, onChange }) => {
  const updateField = (field: keyof ExamPaperData, value: string) => {
    onChange({ ...data, [field]: value });
  };

  const updateSection = (sIdx: number, updates: Partial<ExamSection>) => {
    const newSections = [...data.sections];
    newSections[sIdx] = { ...newSections[sIdx], ...updates };
    onChange({ ...data, sections: newSections });
  };

  const updateQuestion = (sIdx: number, qIdx: number, updates: Partial<ExamQuestion>) => {
    const newSections = [...data.sections];
    const newQuestions = [...newSections[sIdx].questions];
    newQuestions[qIdx] = { ...newQuestions[qIdx], ...updates };
    newSections[sIdx] = { ...newSections[sIdx], questions: newQuestions };
    onChange({ ...data, sections: newSections });
  };

  const addQuestion = (sIdx: number) => {
    const newSections = [...data.sections];
    newSections[sIdx].questions.push({
      id: Math.random().toString(36).substr(2, 9),
      number: (newSections[sIdx].questions.length + 1).toString(),
      text: "New Question",
      marks: "5"
    });
    onChange({ ...data, sections: newSections });
  };

  const removeQuestion = (sIdx: number, qIdx: number) => {
    const newSections = [...data.sections];
    newSections[sIdx].questions.splice(qIdx, 1);
    onChange({ ...data, sections: newSections });
  };

  return (
    <div className="h-full overflow-auto p-6 bg-white border-r border-slate-200 no-print">
      <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
        </svg>
        Paper Editor
      </h2>

      <div className="space-y-6">
        {/* Basic Info */}
        <div className="grid grid-cols-2 gap-4">
          <div className="col-span-2">
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Title / Institution</label>
            <input 
              type="text" 
              value={data.title}
              onChange={(e) => updateField('title', e.target.value)}
              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Subject</label>
            <input 
              type="text" 
              value={data.subject}
              onChange={(e) => updateField('subject', e.target.value)}
              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Total Marks</label>
            <input 
              type="text" 
              value={data.totalMarks}
              onChange={(e) => updateField('totalMarks', e.target.value)}
              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
        </div>

        <hr className="border-slate-100" />

        {/* Sections */}
        {data.sections.map((section, sIdx) => (
          <div key={sIdx} className="bg-slate-50 rounded-xl p-4 space-y-4 border border-slate-200">
            <div className="flex justify-between items-center">
              <input 
                type="text" 
                value={section.title}
                onChange={(e) => updateSection(sIdx, { title: e.target.value })}
                className="font-bold bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-500 focus:bg-white p-1 outline-none transition-all"
              />
              <button 
                onClick={() => addQuestion(sIdx)}
                className="text-xs font-semibold text-blue-600 hover:text-blue-700 flex items-center gap-1"
              >
                + Add Question
              </button>
            </div>

            <div className="space-y-3">
              {section.questions.map((q, qIdx) => (
                <div key={q.id || qIdx} className="group relative bg-white rounded-lg p-3 border border-slate-200 shadow-sm">
                  <div className="flex gap-2 mb-2">
                    <input 
                      type="text" 
                      value={q.number}
                      onChange={(e) => updateQuestion(sIdx, qIdx, { number: e.target.value })}
                      className="w-8 font-bold text-slate-500 outline-none"
                    />
                    <textarea 
                      value={q.text}
                      onChange={(e) => updateQuestion(sIdx, qIdx, { text: e.target.value })}
                      className="flex-1 text-sm bg-transparent outline-none resize-none"
                      rows={2}
                    />
                    <input 
                      type="text" 
                      value={q.marks}
                      onChange={(e) => updateQuestion(sIdx, qIdx, { marks: e.target.value })}
                      className="w-10 text-xs font-bold text-slate-400 outline-none text-right h-fit"
                      placeholder="Pts"
                    />
                  </div>
                  <button 
                    onClick={() => removeQuestion(sIdx, qIdx)}
                    className="absolute -right-2 -top-2 bg-red-100 text-red-600 rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}

        <button 
          onClick={() => onChange({ ...data, sections: [...data.sections, { title: 'New Section', questions: [] }] })}
          className="w-full py-2 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 font-semibold hover:border-slate-300 hover:text-slate-500 transition-all"
        >
          + Add New Section
        </button>
      </div>
    </div>
  );
};

export default EditorSection;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ProcessingState from './components/ProcessingState';
import EditorSection from './components/EditorSection';
import A4Preview from './components/A4Preview';
import { processHandwrittenImage } from './services/geminiService';
import { AppState, ExamPaperData, UploadedFile } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col">
        {appState === AppState.LANDING && (
          <div className="max-w-4xl mx-auto w-full px-4 py-16 flex flex-col gap-12">
            <div className="text-center space-y-4">
              <h1 className="text-5xl font-extrabold text-slate-900 tracking-tight lg:text-6xl">
                Convert Handwriting to <br />
                <span className="text-blue-600">Professional Papers</span>
              </h1>
              <p className="text-xl text-slate-500 max-w-2xl mx-auto">
                Snap a photo of your handwritten notes or exam questions. Our AI handles the OCR, 
                formatting, and layout for a print-ready A4 document in seconds.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-6 py-4 rounded-xl flex items-center gap-3">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                {error}
              </div>
            )}

            <FileUploader onFilesSelected={startProcessing} />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-8">
              {[
                { title: 'AI OCR', desc: 'Powerful handwriting recognition supporting multiple languages.', icon: '✍️' },
                { title: 'Subject Aware', desc: 'Smartly formats headers, questions, and math equations.', icon: '📐' },
                { title: 'PDF & Word', desc: 'Download your finalized paper in professional formats.', icon: '📄' },
              ].map((feature, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                  <div className="text-3xl mb-4">{feature.icon}</div>
                  <h3 className="font-bold text-slate-800 mb-2">{feature.title}</h3>
                  <p className="text-sm text-slate-500 leading-relaxed">{feature.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {appState === AppState.PROCESSING && (
          <div className="flex-1 flex items-center justify-center">
            <ProcessingState />
          </div>
        )}

        {appState === AppState.EDITOR && examData && (
          <div className="flex-1 flex h-[calc(100vh-64px)] overflow-hidden">
            <div className="w-1/3 min-w-[400px] shadow-lg z-10">
              <EditorSection 
                data={examData} 
                onChange={setExamData} 
              />
              <div className="absolute bottom-6 left-6 no-print">
                <button 
                  onClick={handlePrint}
                  className="flex items-center gap-2 px-8 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-xl shadow-blue-200 hover:bg-blue-700 transition-all"
