import { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel, BorderStyle, Table, TableRow, TableCell, WidthType } from "docx";
import { ExamPaperData } from "../types";

export const exportToDocx = async (data: ExamPaperData) => {
  const doc = new Document({
    sections: [
      {
        properties: {},
        children: [
          // Header: Title/School Name
          new Paragraph({
            alignment: AlignmentType.CENTER,
            heading: HeadingLevel.HEADING_1,
            children: [
              new TextRun({
                text: data.title.toUpperCase(),
                bold: true,
                size: 32,
              }),
            ],
          }),

          // Info Table (Subject, Marks, Time)
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.SINGLE, size: 2, color: "000000" },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              new TableRow({
                children: [
                  new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: `Subject: ${data.subject}`, bold: true })] })],
                  }),
                  new TableCell({
                    children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: `Total Marks: ${data.totalMarks}`, bold: true })] })],
                  }),
                ],
              }),
              new TableRow({
                children: [
                  new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: `Time Allowed: ${data.timeAllowed}`, bold: true })] })],
                  }),
                  new TableCell({
                    children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "Roll No: _______________", bold: true })] })],
                  }),
                ],
              }),
            ],
          }),

          new Paragraph({ spacing: { before: 400 } }),

          // Sections and Questions
          ...data.sections.flatMap((section) => [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 200, after: 200 },
              children: [
                new TextRun({
                  text: section.title.toUpperCase(),
                  bold: true,
                  border: {
                    style: BorderStyle.SINGLE,
                    size: 1,
                    color: "000000",
                    space: 4,
                  },
                }),
              ],
            }),

            ...(section.instructions ? [
              new Paragraph({
                spacing: { after: 200 },
                children: [new TextRun({ text: `Instructions: ${section.instructions}`, italic: true, size: 20 })],
              }),
            ] : []),

            ...section.questions.flatMap((q) => [
              new Paragraph({
                spacing: { after: 200 },
                children: [
                  new TextRun({ text: `Q.${q.number}: `, bold: true }),
                  new TextRun({ text: q.text }),
                  ...(q.marks ? [new TextRun({ text: `  (${q.marks})`, bold: true })] : []),
                ],
              }),
              ...(q.subQuestions ? q.subQuestions.map((sub, idx) => 
                new Paragraph({
                  indent: { left: 720 },
                  spacing: { after: 100 },
                  children: [new TextRun({ text: `${String.fromCharCode(97 + idx)}) ${sub}` })],
                })
              ) : []),
            ]),
          ]),

          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 800 },
            children: [new TextRun({ text: "*** END OF PAPER ***", size: 18, color: "666666" })],
          }),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${data.subject || "Exam_Paper"}.docx`;
  a.click();
  window.URL.revokeObjectURL(url);
};

