import React, { useState } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ProcessingState from './components/ProcessingState';
import EditorSection from './components/EditorSection';
import A4Preview from './components/A4Preview';
import { processHandwrittenImage } from './services/geminiService';
import { exportToDocx } from './services/wordExportService';
import { AppState, ExamPaperData, UploadedFile } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isExportingPDF, setIsExportingPDF] = useState(false);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportPDF = () => {
    const element = document.getElementById('pdf-export-target');
    if (!element || !examData) return;

    setIsExportingPDF(true);

    const opt = {
      margin: 0,
      filename: `${examData.subject || 'Exam_Paper'}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 3, useCORS: true, letterRendering: true, logging: false },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    // @ts-ignore
    html2pdf().set(opt).from(element).save().then(() => {
      setIsExportingPDF(false);
    }).catch((err: any) => {
      console.error("PDF Export Error:", err);
      setIsExportingPDF(false);
      alert("Failed to export PDF. Try using the 'System Print' button and selecting 'Save as PDF'.");
    });
  };

  const handleExportWord = async () => {
    if (!examData) return;
    try {
      await exportToDocx(examData);
    } catch (err) {
      console.error("Failed to export Word:", err);
      alert("Could not generate Word document. Please try again.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col">
        {appState === AppState.LANDING && (
          <div className="max-w-4xl mx-auto w-full px-4 py-16 flex flex-col gap-12">
            <div className="text-center space-y-4">
              <h1 className="text-5xl font-extrabold text-slate-900 tracking-tight lg:text-6xl">
                Convert Handwriting to <br />
                <span className="text-blue-600">Professional Papers</span>
              </h1>
              <p className="text-xl text-slate-500 max-w-2xl mx-auto">
                Snap a photo of your handwritten notes or exam questions. Our AI handles the OCR, 
                formatting, and layout for a print-ready A4 document in seconds.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-6 py-4 rounded-xl flex items-center gap-3">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                {error}
              </div>
            )}

            <FileUploader onFilesSelected={startProcessing} />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-8">
              {[
                { title: 'AI OCR', desc: 'Powerful handwriting recognition supporting multiple languages.', icon: '✍️' },
                { title: 'Subject Aware', desc: 'Smartly formats headers, questions, and math equations.', icon: '📐' },
                { title: 'PDF & Word', desc: 'Download your finalized paper in professional formats.', icon: '📄' },
              ].map((feature, i) => (
                <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
                  <div className="text-3xl mb-4">{feature.icon}</div>
                  <h3 className="font-bold text-slate-800 mb-2">{feature.title}</h3>
                  <p className="text-sm text-slate-500 leading-relaxed">{feature.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {appState === AppState.PROCESSING && (
          <div className="flex-1 flex items-center justify-center">
            <ProcessingState />
          </div>
        )}

        {appState === AppState.EDITOR && examData && (
          <div className="flex-1 flex h-[calc(100vh-64px)] overflow-hidden">
            <div className="w-1/3 min-w-[400px] shadow-lg z-10 flex flex-col">
              <div className="flex-1 overflow-auto">
                <EditorSection 
                  data={examData} 
                  onChange={setExamData} 
                />
              </div>
              <div className="p-6 bg-slate-50 border-t border-slate-200 no-print space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={handleExportPDF}
                    disabled={isExportingPDF}
                    className={`flex items-center justify-center gap-2 px-4 py-3 bg-red-600 text-white rounded-xl font-bold shadow-lg hover:bg-red-700 transition-all shadow-red-100 ${isExportingPDF ? 'opacity-50 cursor-not-allowed' : ''}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                    </svg>
                    {isExportingPDF ? 'Wait...' : 'Export PDF'}
                  </button>
                  <button 
                    onClick={handleExportWord}
                    className="flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all shadow-blue-100"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Word (.docx)
                  </button>
                </div>
                <button 
                  onClick={handlePrint}
                  className="w-full flex items-center justify-center gap-2 px-6 py-2 border border-slate-300 text-slate-600 rounded-xl font-medium hover:bg-slate-100 transition-all"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  System Print
                </button>
              </div>
            </div>
            <div className="flex-1 bg-slate-300 overflow-auto p-8 flex items-start justify-center">
              <A4Preview data={examData} />
            </div>
          </div>
        )}
      </main>

      {/* Hidden elements for Export and Print consistency */}
      {examData && (
        <div className="absolute top-[-10000px] left-[-10000px]">
          <A4Preview data={examData} id="pdf-export-target" isPrintVersion={true} />
        </div>
      )}

      {/* Browser Print Container */}
      {appState === AppState.EDITOR && examData && (
        <div className="hidden print:block fixed inset-0 bg-white z-[9999] print-paper-container">
           <A4Preview data={examData} isPrintVersion={true} />
        </div>
      )}

      {/* Footer Branding */}
      {appState === AppState.LANDING && (
        <footer className="no-print border-t border-slate-200 py-12 bg-white">
          <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 bg-slate-900 rounded-md flex items-center justify-center text-white text-[10px] font-bold">
                P
              </div>
              <span className="font-bold text-slate-900 tracking-tight">Paper Composer</span>
            </div>
            <p className="text-slate-400 text-sm">
              &copy; 2024 Paper Composer AI. All rights reserved.
            </p>
            <div className="flex gap-6 text-sm font-medium text-slate-500">
              <a href="#" className="hover:text-blue-600">Privacy</a>
              <a href="#" className="hover:text-blue-600">Terms</a>
              <a href="#" className="hover:text-blue-600">Contact</a>
            </div>
          </div>
        </footer>
      )}
    </div>
  );
};

