import ProcessingState from './components/ProcessingState';
import EditorSection from './components/EditorSection';
import A4Preview from './components/A4Preview';
import { processHandwrittenImage } from './services/geminiService';
import { exportToDocx } from './services/wordExportService';
import { AppState, ExamPaperData, UploadedFile } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isExportingPDF, setIsExportingPDF] = useState(false);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportPDF = () => {
    const element = document.getElementById('pdf-export-content');
    if (!element || !examData) return;

    setIsExportingPDF(true);

    // Using html2pdf with specific settings for A4 clarity
    const opt = {
      margin: 0,
      filename: `${examData.subject || 'Exam_Paper'}.pdf`,
      image: { type: 'jpeg', quality: 1 },
      html2canvas: { 
        scale: 4, 
        useCORS: true, 
        letterRendering: true, 
        logging: false,
        backgroundColor: '#ffffff'
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait', compress: true }
    };

    // @ts-ignore
    html2pdf().set(opt).from(element).toPdf().save().then(() => {
      setIsExportingPDF(false);
    }).catch((err: any) => {
      console.error("PDF Export Error:", err);
      setIsExportingPDF(false);
      alert("PDF generation failed. Use 'System Print' instead.");
    });
  };

  const handleExportWord = async () => {
    if (!examData) return;
    try {
      await exportToDocx(examData);
    } catch (err) {
      console.error("Failed to export Word:", err);
      alert("Word export failed.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col font-sans">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col overflow-hidden">
        {appState === AppState.LANDING && (
          <div className="max-w-4xl mx-auto w-full px-4 py-16 flex flex-col gap-12">
            <div className="text-center space-y-6">
              <h1 className="text-5xl font-extrabold text-slate-900 tracking-tight lg:text-7xl leading-[1.1]">
                Your Handwritten Notes<br />
                <span className="text-blue-600">Perfectly Composed.</span>
              </h1>
              <p className="text-xl text-slate-500 max-w-2xl mx-auto font-medium">
                Instantly turn exam photos into professional A4 papers. 
                AI handles the text, math, and professional layout.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-6 py-4 rounded-2xl flex items-center gap-3 animate-bounce">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <span className="font-semibold">{error}</span>
              </div>
            )}

            <FileUploader onFilesSelected={startProcessing} />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {[
                { title: 'Super OCR', desc: 'Detects messy handwriting with 99% accuracy.', icon: '⚡' },
                { title: 'Smart Layout', desc: 'Auto-aligns headers, questions, and mark schemes.', icon: '📏' },
                { title: 'Instant PDF', desc: 'Ready for print or digital distribution immediately.', icon: '🖨️' },
              ].map((feature, i) => (
                <div key={i} className="bg-white p-8 rounded-3xl shadow-[0_4px_20px_rgba(0,0,0,0.03)] border border-slate-100 hover:scale-105 transition-transform">
                  <div className="text-4xl mb-4">{feature.icon}</div>
                  <h3 className="font-bold text-slate-900 text-lg mb-2">{feature.title}</h3>
                  <p className="text-sm text-slate-500 leading-relaxed font-medium">{feature.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {appState === AppState.PROCESSING && (
          <div className="flex-1 flex items-center justify-center bg-white/80 backdrop-blur-sm">
            <ProcessingState />
          </div>
        )}

        {appState === AppState.EDITOR && examData && (
          <div className="flex-1 flex h-full overflow-hidden bg-slate-100">
            {/* Editor Sidebar */}
            <div className="w-[420px] flex flex-col bg-white border-r border-slate-200 shadow-xl z-20">
              <div className="flex-1 overflow-auto">
                <EditorSection data={examData} onChange={setExamData} />
              </div>
              <div className="p-6 bg-slate-50 border-t border-slate-200 no-print space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={handleExportPDF}
                    disabled={isExportingPDF}
                    className={`flex items-center justify-center gap-2 px-4 py-3 bg-red-600 text-white rounded-2xl font-bold shadow-lg shadow-red-100 hover:bg-red-700 transition-all ${isExportingPDF ? 'opacity-50 cursor-not-allowed animate-pulse' : 'hover:-translate-y-1'}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                    </svg>
                    {isExportingPDF ? 'Wait...' : 'Export PDF'}
                  </button>
                  <button 
                    onClick={handleExportWord}
                    className="flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 hover:-translate-y-1 transition-all"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Word Doc
                  </button>
                </div>
                <button 
                  onClick={handlePrint}
                  className="w-full flex items-center justify-center gap-2 px-6 py-3 border-2 border-slate-200 text-slate-700 rounded-2xl font-bold hover:bg-slate-100 transition-all"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  System Print (Control + P)
                </button>
              </div>
            </div>

            {/* Preview Area */}
            <div className="flex-1 overflow-auto p-12 flex justify-center items-start scroll-smooth">
              <A4Preview data={examData} />
            </div>
          </div>
        )}
      </main>

      {/* Off-screen Export Container - Guaranteed to be visible to html2pdf but invisible to user */}
      <div className="fixed -left-[10000px] top-0 pointer-events-none">
        {examData && (
          <div id="pdf-export-content">
            <A4Preview data={examData} isExportVersion={true} />
          </div>
        )}
      </div>

      {/* Print-only container */}
      <div className="hidden print:block print-container">
        {examData && <A4Preview data={examData} isExportVersion={true} />}
      </div>

      {/* Footer Branding - Landing Only */}
      {appState === AppState.LANDING && (
        <footer className="no-print border-t border-slate-200 py-12 bg-white">
          <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-slate-900 rounded-xl flex items-center justify-center text-white text-sm font-bold">
                P
              </div>
              <span className="font-bold text-slate-900 tracking-tight text-lg">Paper Composer AI</span>
            </div>
            <p className="text-slate-400 text-sm font-medium">
              &copy; 2024 Vibe Coding Lab. Fast, Professional, Easy.
            </p>
          </div>
        </footer>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { ExamPaperData } from '../types';

interface A4PreviewProps {
  data: ExamPaperData;
  id?: string;
  isExportVersion?: boolean;
}

const A4Preview: React.FC<A4PreviewProps> = ({ data, id, isExportVersion = false }) => {
  return (
    <div 
      id={id}
      className={`a4-page bg-white text-black ${!isExportVersion ? 'shadow-2xl origin-top scale-[0.85] lg:scale-100' : ''}`} 
      style={{
        width: '210mm',
        minHeight: '297mm',
        padding: '15mm 15mm', // Slightly reduced padding to ensure content fits
        fontFamily: "'Times New Roman', Times, serif",
        boxSizing: 'border-box',
        color: 'black',
        backgroundColor: 'white',
        lineHeight: '1.5',
        position: 'relative',
        margin: isExportVersion ? '0' : '0 auto'
      }}
    >
      {/* Header / School Name */}
      <div className="text-center mb-8">
        <h1 className="text-[26pt] font-bold uppercase tracking-tight leading-none mb-1">
          {data.title || "EXAMINATION PAPER"}
        </h1>
        <div className="w-full h-0.5 bg-black mt-4"></div>
      </div>

      {/* Info Details Grid */}
      <div className="grid grid-cols-2 gap-x-8 gap-y-3 mb-10 text-[12pt]">
        <div className="flex items-end">
          <span className="font-bold mr-2 whitespace-nowrap">Subject:</span>
          <span className="flex-1 border-b border-black pb-0.5">{data.subject}</span>
        </div>
        <div className="flex items-end">
          <span className="font-bold mr-2 whitespace-nowrap">Total Marks:</span>
          <span className="flex-1 border-b border-black pb-0.5">{data.totalMarks}</span>
        </div>
        <div className="flex items-end">
          <span className="font-bold mr-2 whitespace-nowrap">Time Allowed:</span>
          <span className="flex-1 border-b border-black pb-0.5">{data.timeAllowed}</span>
        </div>
        <div className="flex items-end">
          <span className="font-bold mr-2 whitespace-nowrap">Roll No:</span>
          <span className="flex-1 border-b border-black pb-0.5"></span>
        </div>
      </div>

      {/* Content Sections */}
      <div className="space-y-12">
        {data.sections.map((section, sIdx) => (
          <div key={sIdx} className="section break-inside-avoid">
            {/* Section Heading */}
            <div className="flex justify-center mb-6">
              <div className="border-2 border-black px-10 py-2 inline-block">
                <h2 className="text-[14pt] font-bold uppercase tracking-widest">
                  {section.title}
                </h2>
              </div>
            </div>

            {section.instructions && (
              <p className="italic text-[11pt] mb-6 text-center text-gray-800">
                (Instructions: {section.instructions})
              </p>
            )}

            {/* Questions List */}
            <div className="space-y-8">
              {section.questions.map((q, qIdx) => (
                <div key={q.id || qIdx} className="question-block flex gap-5 break-inside-avoid">
                  <div className="font-bold text-[12pt] min-w-[50px]">
                    Q.{q.number}
                  </div>
                  <div className="flex-1 text-[12pt]">
                    <div className="flex justify-between items-start">
                      <div className="flex-1 whitespace-pre-wrap leading-relaxed text-justify">
                        {q.text}
                      </div>
                      {q.marks && (
                        <div className="font-bold text-[11pt] italic ml-6 whitespace-nowrap pt-1">
                          ({q.marks})
                        </div>
                      )}
                    </div>

                    {q.subQuestions && q.subQuestions.length > 0 && (
                      <div className="mt-4 space-y-3 pl-8">
                        {q.subQuestions.map((sub, subIdx) => (
                          <div key={subIdx} className="flex gap-4">
                            <span className="font-bold">({String.fromCharCode(97 + subIdx)})</span>
                            <span className="flex-1">{sub}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Paper Footer */}
      <div className="mt-20 text-center border-t border-gray-300 pt-8">
        <p className="text-[10pt] font-bold tracking-[0.5em] text-gray-500">
          *** END OF PAPER ***
        </p>
      </div>
    </div>
  );
};

export default A4Preview;

import React, { useState } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ProcessingState from './components/ProcessingState';
import EditorSection from './components/EditorSection';
import A4Preview from './components/A4Preview';
import { processHandwrittenImage } from './services/geminiService';
import { exportToDocx } from './services/wordExportService';
import { AppState, ExamPaperData, UploadedFile } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isExportingPDF, setIsExportingPDF] = useState(false);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportPDF = () => {
    const element = document.getElementById('pdf-export-content');
    if (!element || !examData) return;

    setIsExportingPDF(true);

    // Optimized html2pdf settings for exact A4 fit
    const opt = {
      margin: 0,
      filename: `${examData.subject || 'Exam_Paper'}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2, // Sufficient for high quality without bloat
        useCORS: true, 
        letterRendering: true,
        backgroundColor: '#ffffff'
      },
      jsPDF: { 
        unit: 'mm', 
        format: 'a4', 
        orientation: 'portrait',
        precision: 32 // Increase precision for cleaner lines
      }
    };

    // @ts-ignore
    html2pdf().set(opt).from(element).save().then(() => {
      setIsExportingPDF(false);
    }).catch((err: any) => {
      console.error("PDF Export Error:", err);
      setIsExportingPDF(false);
      alert("Failed to export PDF. Please use System Print instead.");
    });
  };

  const handleExportWord = async () => {
    if (!examData) return;
    try {
      await exportToDocx(examData);
    } catch (err) {
      console.error("Failed to export Word:", err);
      alert("Word export failed.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col font-sans selection:bg-blue-100 selection:text-blue-900">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col overflow-hidden">
        {appState === AppState.LANDING && (
          <div className="max-w-4xl mx-auto w-full px-4 py-16 flex flex-col gap-12">
            <div className="text-center space-y-6">
              <h1 className="text-5xl font-extrabold text-slate-900 tracking-tight lg:text-7xl leading-[1.1]">
                Convert Handwriting to <br />
                <span className="text-blue-600 underline decoration-blue-100 underline-offset-8">Composed Papers</span>
              </h1>
              <p className="text-xl text-slate-500 max-w-2xl mx-auto font-medium leading-relaxed">
                Scan your handwritten exam sheets and get a perfectly formatted 
                A4 digital paper in seconds. Ready for school or college.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 border-l-4 border-red-500 text-red-700 px-6 py-4 rounded-r-2xl flex items-center gap-3 shadow-sm">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <span className="font-semibold">{error}</span>
              </div>
            )}

            <FileUploader onFilesSelected={startProcessing} />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {[
                { title: 'AI OCR', desc: 'Reads even the messiest handwriting using advanced AI.', icon: '🧠' },
                { title: 'A4 Layout', desc: 'Auto-adjusts margins and spacing for professional prints.', icon: '📄' },
                { title: 'Export Ready', desc: 'Save as high-quality PDF or editable Word document.', icon: '💾' },
              ].map((feature, i) => (
                <div key={i} className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm transition-all hover:shadow-md">
                  <div className="text-4xl mb-4">{feature.icon}</div>
                  <h3 className="font-bold text-slate-900 text-lg mb-2">{feature.title}</h3>
                  <p className="text-sm text-slate-500 leading-relaxed font-medium">{feature.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {appState === AppState.PROCESSING && (
          <div className="flex-1 flex items-center justify-center bg-white/60 backdrop-blur-md">
            <ProcessingState />
          </div>
        )}

        {appState === AppState.EDITOR && examData && (
          <div className="flex-1 flex h-full overflow-hidden bg-slate-50">
            {/* Left Sidebar: Editor */}
            <div className="w-[420px] flex flex-col bg-white border-r border-slate-200 shadow-2xl z-20">
              <div className="flex-1 overflow-auto preview-scroll-container">
                <EditorSection data={examData} onChange={setExamData} />
              </div>
              <div className="p-6 bg-slate-50 border-t border-slate-200 no-print space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={handleExportPDF}
                    disabled={isExportingPDF}
                    className={`flex items-center justify-center gap-2 px-4 py-3 bg-red-600 text-white rounded-2xl font-bold shadow-lg shadow-red-100 hover:bg-red-700 transition-all ${isExportingPDF ? 'opacity-50 cursor-wait' : 'hover:-translate-y-1'}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    {isExportingPDF ? 'Processing...' : 'Export PDF'}
                  </button>
                  <button 
                    onClick={handleExportWord}
                    className="flex items-center justify-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 hover:-translate-y-1 transition-all"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Word Doc
                  </button>
                </div>
                <button 
                  onClick={handlePrint}
                  className="w-full flex items-center justify-center gap-2 px-6 py-3 border-2 border-slate-200 text-slate-700 rounded-2xl font-bold hover:bg-white hover:border-blue-300 hover:text-blue-600 transition-all"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  System Print
                </button>
              </div>
            </div>

            {/* Right: Preview Area */}
            <div className="flex-1 overflow-auto p-12 flex justify-center items-start scroll-smooth bg-slate-200 shadow-inner">
              <A4Preview data={examData} />
            </div>
          </div>
        )}
      </main>

      {/* Hidden container for PDF export - uses exactly A4 dimensions without bleed */}
      <div className="fixed -left-[2000mm] top-0 pointer-events-none" style={{ width: '210mm' }}>
        {examData && (
          <div id="pdf-export-content" style={{ background: 'white' }}>
            <A4Preview data={examData} isExportVersion={true} />
          </div>
        )}
      </div>

      {/* System Print container */}
      <div className="hidden print:block print-only-container">
        {examData && <A4Preview data={examData} isExportVersion={true} />}
      </div>

      {/* Footer (Landing only) */}
      {appState === AppState.LANDING && (
        <footer className="no-print border-t border-slate-200 py-12 bg-white mt-auto">
          <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center text-white text-sm font-bold">
                P
              </div>
              <span className="font-bold text-slate-900 tracking-tight text-lg">Paper Composer AI</span>
            </div>
            <p className="text-slate-400 text-sm font-medium">
              Made for Teachers and Students. Professional quality documents.
            </p>
          </div>
        </footer>
      )}
    </div>
  );
};

export default App;

