import React, { useState } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ProcessingState from './components/ProcessingState';
import EditorSection from './components/EditorSection';
import A4Preview from './components/A4Preview';
import { processHandwrittenImage } from './services/geminiService';
import { exportToDocx } from './services/wordExportService';
import { AppState, ExamPaperData, UploadedFile } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isExportingPDF, setIsExportingPDF] = useState(false);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportPDF = async () => {
    const element = document.getElementById('pdf-export-content');
    if (!element || !examData) return;

    setIsExportingPDF(true);

    // Config for html2pdf to ensure clean multi-page A4
    const opt = {
      margin: 0,
      filename: `${examData.subject.replace(/\s+/g, '_') || 'Exam_Paper'}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2.5, 
        useCORS: true, 
        letterRendering: true,
        backgroundColor: '#ffffff',
        // Critical: Ensure the element is rendered in a "virtual" A4 width
        width: 794, // Approx 210mm in pixels at 96dpi
      },
      jsPDF: { 
        unit: 'mm', 
        format: 'a4', 
        orientation: 'portrait',
        compress: true,
      },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };

    try {
      // @ts-ignore
      await html2pdf().set(opt).from(element).save();
    } catch (err: any) {
      console.error("PDF Export Error:", err);
      alert("PDF generation failed. Use 'System Print' and select 'Save as PDF' as a workaround.");
    } finally {
      setIsExportingPDF(false);
    }
  };

  const handleExportWord = async () => {
    if (!examData) return;
    try {
      await exportToDocx(examData);
    } catch (err) {
      console.error("Failed to export Word:", err);
      alert("Word export failed. Please try again.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col font-sans">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col overflow-hidden">
        {appState === AppState.LANDING && (
          <div className="max-w-4xl mx-auto w-full px-4 py-16 flex flex-col gap-12">
            <div className="text-center space-y-6">
              <h1 className="text-5xl font-extrabold text-slate-900 tracking-tight lg:text-7xl leading-[1.1]">
                Your Handwriting,<br />
                <span className="text-blue-600">Perfectly Typed.</span>
              </h1>
              <p className="text-xl text-slate-500 max-w-2xl mx-auto font-medium">
                Snap photos of your handwritten exam papers. We'll convert them into professional, 
                print-ready A4 documents using advanced AI.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 border-l-4 border-red-500 text-red-700 px-6 py-4 rounded-r-2xl flex items-center gap-3 shadow-md animate-pulse">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <span className="font-semibold">{error}</span>
              </div>
