import { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel, BorderStyle, Table, TableRow, TableCell, WidthType, SpacingVerticalAlign } from "docx";
import { ExamPaperData } from "../types";

export const exportToDocx = async (data: ExamPaperData) => {
  const doc = new Document({
    styles: {
      default: {
        document: {
          run: {
            font: "Times New Roman",
            size: 24, // 12pt
          },
        },
      },
    },
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: 1440, // 1 inch
              right: 1440,
              bottom: 1440,
              left: 1440,
            },
          },
        },
        children: [
          // Header: Title/School Name
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [
              new TextRun({
                text: data.title.toUpperCase(),
                bold: true,
                size: 44, // 22pt
              }),
            ],
            spacing: { after: 200 },
          }),

          // Horizontal Line (Divider)
          new Paragraph({
            border: {
              bottom: { style: BorderStyle.SINGLE, size: 12, color: "000000" },
            },
            spacing: { after: 300 },
          }),

          // Info Table (Subject, Marks, Time)
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              new TableRow({
                children: [
                  new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: "Subject: ", bold: true }), new TextRun({ text: data.subject, underline: {} })] })],
                  }),
                  new TableCell({
                    children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "Total Marks: ", bold: true }), new TextRun({ text: data.totalMarks, underline: {} })] })],
                  }),
                ],
              }),
              new TableRow({
                children: [
                  new TableCell({
                    children: [new Paragraph({ spacing: { before: 100 }, children: [new TextRun({ text: "Time Allowed: ", bold: true }), new TextRun({ text: data.timeAllowed, underline: {} })] })],
                  }),
                  new TableCell({
                    children: [new Paragraph({ spacing: { before: 100 }, alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "Roll No: _______________", bold: true })] })],
                  }),
                ],
              }),
            ],
          }),

          new Paragraph({ spacing: { before: 600 } }),

          // Sections and Questions
          ...data.sections.flatMap((section) => [
            // Section Header
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 400, after: 400 },
              children: [
                new TextRun({
                  text: `  ${section.title.toUpperCase()}  `,
                  bold: true,
                  size: 28, // 14pt
                  border: {
                    style: BorderStyle.SINGLE,
                    size: 6,
                    color: "000000",
                    space: 12,
                  },
                }),
              ],
            }),

            ...(section.instructions ? [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { after: 300 },
                children: [new TextRun({ text: `(Instructions: ${section.instructions})`, italic: true, size: 22 })],
              }),
            ] : []),

            ...section.questions.flatMap((q) => [
              // Question Text
              new Paragraph({
                spacing: { before: 200, after: 150 },
                alignment: AlignmentType.BOTH,
                children: [
                  new TextRun({ text: `Q.${q.number}  `, bold: true }),
                  new TextRun({ text: q.text }),
                  ...(q.marks ? [new TextRun({ text: `\t(${q.marks})`, bold: true })] : []),
                ],
                tabStops: [
                  {
                    type: AlignmentType.RIGHT,
                    position: 9000,
                  },
                ],
              }),

              // Sub questions
              ...(q.subQuestions ? q.subQuestions.map((sub, idx) => 
                new Paragraph({
                  indent: { left: 720 }, // 0.5 inch
                  spacing: { after: 100 },
                  children: [new TextRun({ text: `(${String.fromCharCode(97 + idx)})  ${sub}` })],
                })
              ) : []),
            ]),
          ]),

          // Final Footer
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 1000 },
            children: [
              new TextRun({ 
                text: "*** END OF PAPER ***", 
                bold: true,
                size: 20, 
                color: "888888" 
              })
            ],
          }),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${data.subject.replace(/\s+/g, '_') || "Exam_Paper"}.docx`;
  a.click();
  window.URL.revokeObjectURL(url);
};

