  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
