  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isExportingPDF, setIsExportingPDF] = useState(false);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Failed to process paper. Please ensure images are clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportPDF = async () => {
    const element = document.getElementById('pdf-export-content');
    if (!element || !examData) return;

    setIsExportingPDF(true);

    // Fine-tuned options to solve blank page and alignment issues
    const opt = {
      margin: 0,
      filename: `${(examData.subject || 'Exam_Paper').replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        letterRendering: true,
        backgroundColor: '#ffffff',
        width: 794, // 210mm at 96dpi
        logging: false,
      },
      jsPDF: { 
        unit: 'mm', 
        format: 'a4', 
        orientation: 'portrait',
        compress: true,
      },
      // Fixed page-breaking to avoid orphan sections and blank pages
      pagebreak: { mode: 'css' } 
    };

    try {
      // @ts-ignore
      await html2pdf().set(opt).from(element).save();
    } catch (err: any) {
      console.error("PDF Export Error:", err);
      alert("PDF generation failed. Use 'Direct System Print' as a backup.");
    } finally {
      setIsExportingPDF(false);
    }
  };

  const handleExportWord = async () => {
    if (!examData) return;
    try {
      await exportToDocx(examData);
    } catch (err) {
      console.error("Failed to export Word:", err);
      alert("Word export failed. Please try again.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col font-sans">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col overflow-hidden">
