import { Document, Packer, Paragraph, TextRun, AlignmentType, BorderStyle, Table, TableRow, TableCell, WidthType } from "docx";
import { ExamPaperData } from "../types";

export const exportToDocx = async (data: ExamPaperData) => {
  const doc = new Document({
    styles: {
      default: {
        document: {
          run: {
            font: "Times New Roman",
            size: 24, // 12pt
          },
        },
      },
    },
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: 1140, // ~0.8 inch
              right: 1140,
              bottom: 1140,
              left: 1140,
            },
          },
        },
        children: [
          // Header: Title
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [
              new TextRun({
                text: data.title.toUpperCase(),
                bold: true,
                size: 40, // 20pt
              }),
            ],
            spacing: { after: 120 },
          }),

          // Divider Line
          new Paragraph({
            border: {
              bottom: { style: BorderStyle.SINGLE, size: 12, color: "000000" },
            },
            spacing: { after: 240 },
          }),

          // Info Grid
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              new TableRow({
                children: [
                  new TableCell({
                    width: { size: 70, type: WidthType.PERCENTAGE },
                    children: [
                      new Paragraph({
                        children: [
                          new TextRun({ text: "Subject: ", bold: true }),
                          new TextRun({ text: data.subject, underline: {} }),
                        ],
                      }),
                    ],
                  }),
                  new TableCell({
                    width: { size: 30, type: WidthType.PERCENTAGE },
                    children: [
                      new Paragraph({
                        alignment: AlignmentType.RIGHT,
                        children: [
                          new TextRun({ text: "Total Marks: ", bold: true }),
                          new TextRun({ text: data.totalMarks, underline: {} }),
                        ],
                      }),
                    ],
                  }),
                ],
              }),
              new TableRow({
                children: [
                  new TableCell({
                    children: [
                      new Paragraph({
                        spacing: { before: 120 },
                        children: [
                          new TextRun({ text: "Time Allowed: ", bold: true }),
                          new TextRun({ text: data.timeAllowed, underline: {} }),
                        ],
                      }),
                    ],
                  }),
                  new TableCell({
                    children: [
                      new Paragraph({
                        alignment: AlignmentType.RIGHT,
                        spacing: { before: 120 },
                        children: [
                          new TextRun({ text: "Roll No: ", bold: true }),
                          new TextRun({ text: "__________", underline: {} }),
                        ],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          }),

          new Paragraph({ spacing: { before: 400 } }),

          // Content
          ...data.sections.flatMap((section) => [
            // Section Title Box
            new Table({
              alignment: AlignmentType.CENTER,
              width: { size: 60, type: WidthType.PERCENTAGE },
              rows: [
                new TableRow({
                  children: [
                    new TableCell({
                      children: [
                        new Paragraph({
                          alignment: AlignmentType.CENTER,
                          children: [
                            new TextRun({
                              text: section.title.toUpperCase(),
                              bold: true,
                              size: 26, // 13pt
                            }),
                          ],
                        }),
                      ],
                      margins: { top: 100, bottom: 100, left: 100, right: 100 },
                      borders: {
                        top: { style: BorderStyle.SINGLE, size: 12 },
                        bottom: { style: BorderStyle.SINGLE, size: 12 },
                        left: { style: BorderStyle.SINGLE, size: 12 },
                        right: { style: BorderStyle.SINGLE, size: 12 },
                      },
                    }),
                  ],
                }),
              ],
            }),

            ...(section.instructions ? [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { before: 200, after: 200 },
                children: [
                  new TextRun({ text: `(Instructions: ${section.instructions})`, italic: true, size: 20 }),
                ],
              }),
            ] : [new Paragraph({ spacing: { before: 200 } })]),

            ...section.questions.flatMap((q) => [
              new Paragraph({
                spacing: { before: 200, after: 100 },
                children: [
                  new TextRun({ text: `Q.${q.number}\t`, bold: true }),
                  new TextRun({ text: q.text }),
                  ...(q.marks ? [new TextRun({ text: `\t[${q.marks}]`, bold: true })] : []),
                ],
                tabStops: [
                  { type: AlignmentType.LEFT, position: 720 }, // Q. number indent
                  { type: AlignmentType.RIGHT, position: 9000 }, // Marks right align
                ],
              }),
              ...(q.subQuestions ? q.subQuestions.map((sub, idx) => 
                new Paragraph({
                  indent: { left: 1080 },
                  spacing: { before: 100 },
                  children: [
                    new TextRun({ text: `(${String.fromCharCode(97 + idx)})  ${sub}` }),
                  ],
                })
              ) : []),
            ]),
            new Paragraph({ spacing: { before: 400 } }),
          ]),

          // Footer
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 600 },
            border: {
              top: { style: BorderStyle.SINGLE, size: 6 },
              bottom: { style: BorderStyle.SINGLE, size: 6 },
            },
            children: [
              new TextRun({ 
                text: "   *** END OF PAPER ***   ", 
                bold: true, 
                size: 22 
              }),
            ],
          }),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${data.subject.replace(/\s+/g, '_') || "Exam_Paper"}.docx`;
  a.click();
  window.URL.revokeObjectURL(url);
};

import React, { useState } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ProcessingState from './components/ProcessingState';
import EditorSection from './components/EditorSection';
import A4Preview from './components/A4Preview';
import { processHandwrittenImage } from './services/geminiService';
import { exportToDocx } from './services/wordExportService';
import { AppState, ExamPaperData, UploadedFile } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.LANDING);
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [examData, setExamData] = useState<ExamPaperData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isExportingPDF, setIsExportingPDF] = useState(false);

  const reset = () => {
    setAppState(AppState.LANDING);
    setUploadedFiles([]);
    setExamData(null);
    setError(null);
  };

  const startProcessing = async (files: UploadedFile[]) => {
    setUploadedFiles(files);
    setAppState(AppState.PROCESSING);
    setError(null);

    try {
      const base64Images = files.map(f => f.preview);
      const result = await processHandwrittenImage(base64Images);
      setExamData(result);
      setAppState(AppState.EDITOR);
    } catch (err: any) {
      console.error(err);
      setError("Paper Composition Failed. Please make sure the image is clear and try again.");
      setAppState(AppState.LANDING);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleExportPDF = async () => {
    const element = document.getElementById('pdf-export-content');
    if (!element || !examData) return;

    setIsExportingPDF(true);

    // High-fidelity PDF configuration
    // Using html2pdf-specific options to ensure clarity and multi-page support
    const opt = {
      margin: 0,
      filename: `${(examData.subject || 'Exam_Paper').replace(/\s+/g, '_')}_Final.pdf`,
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        letterRendering: true,
        backgroundColor: '#ffffff',
        width: 794, // Standard A4 width at 96dpi (210mm)
        logging: false,
      },
      jsPDF: { 
        unit: 'mm', 
        format: 'a4', 
        orientation: 'portrait',
        compress: true,
      },
      pagebreak: { mode: ['css', 'legacy'] } 
    };

    try {
      // @ts-ignore
      await html2pdf().set(opt).from(element).save();
    } catch (err: any) {
      console.error("PDF Export Error:", err);
      alert("Something went wrong during PDF generation. Try using 'Direct System Print' as a fallback.");
    } finally {
      setIsExportingPDF(false);
    }
  };

  const handleExportWord = async () => {
    if (!examData) return;
    try {
      await exportToDocx(examData);
    } catch (err) {
      console.error("Word Export Error:", err);
      alert("Word document generation failed. Please check your data and try again.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col font-sans selection:bg-blue-100">
      <Header onReset={reset} />

      <main className="flex-1 flex flex-col overflow-hidden">
        {appState === AppState.LANDING && (
          <div className="max-w-5xl mx-auto w-full px-6 py-16 flex flex-col gap-16">
            <div className="text-center space-y-8">
              <div className="inline-flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-700 rounded-full text-sm font-bold border border-blue-100">
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-blue-500"></span>
                </span>
                Powered by Gemini AI
              </div>
              <h1 className="text-6xl font-extrabold text-slate-900 tracking-tight lg:text-8xl leading-[1.05]">
                Draft by hand.<br />
                <span className="text-blue-600">Print by AI.</span>
              </h1>
              <p className="text-2xl text-slate-500 max-w-3xl mx-auto font-medium leading-relaxed">
                Convert messy handwritten notes and exam papers into structured, 
                high-fidelity A4 documents ready for distribution.
              </p>
            </div>

            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-8 py-5 rounded-3xl flex items-center gap-4 shadow-sm animate-in fade-in slide-in-from-top-4">
                <div className="bg-red-100 p-2 rounded-xl">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
                <span className="font-bold">{error}</span>
              </div>
            )}

            <FileUploader onFilesSelected={startProcessing} />

            <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
              {[
                { title: 'Neural OCR', desc: 'State-of-the-art vision models handle cursive, messy, and technical handwriting.', icon: '🧠' },
                { title: 'Dynamic Layout', desc: 'Intelligent sectioning and mark-scheme alignment based on context.', icon: '📐' },
                { title: 'Smart Cleanup', desc: 'Auto-corrects spelling errors and re-formats mathematical syntax.', icon: '✨' },
              ].map((feature, i) => (
                <div key={i} className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-sm transition-all hover:shadow-xl hover:-translate-y-2">
                  <div className="text-5xl mb-6">{feature.icon}</div>
                  <h3 className="font-extrabold text-slate-900 text-xl mb-3">{feature.title}</h3>
                  <p className="text-slate-500 leading-relaxed font-medium">{feature.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {appState === AppState.PROCESSING && (
          <div className="flex-1 flex items-center justify-center bg-white/40 backdrop-blur-xl">
            <ProcessingState />
          </div>
        )}

        {appState === AppState.EDITOR && examData && (
          <div className="flex-1 flex h-full overflow-hidden bg-slate-100">
            {/* Editor Panel */}
            <div className="w-[450px] flex flex-col bg-white border-r border-slate-200 shadow-2xl z-20 overflow-hidden">
              <div className="flex-1 overflow-auto preview-scroll-container">
                <EditorSection data={examData} onChange={setExamData} />
              </div>
              <div className="p-8 bg-slate-50 border-t border-slate-200 no-print space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <button 
                    onClick={handleExportPDF}
                    disabled={isExportingPDF}
                    className={`flex items-center justify-center gap-2 px-6 py-4 bg-red-600 text-white rounded-[1.25rem] font-bold shadow-xl shadow-red-100 hover:bg-red-700 transition-all ${isExportingPDF ? 'opacity-50 cursor-wait' : 'hover:-translate-y-1'}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    {isExportingPDF ? 'Generating...' : 'Export PDF'}
                  </button>
                  <button 
                    onClick={handleExportWord}
                    className="flex items-center justify-center gap-2 px-6 py-4 bg-blue-600 text-white rounded-[1.25rem] font-bold shadow-xl shadow-blue-100 hover:bg-blue-700 hover:-translate-y-1 transition-all"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Word Doc
                  </button>
                </div>
                <button 
                  onClick={handlePrint}
                  className="w-full flex items-center justify-center gap-2 px-6 py-4 border-2 border-slate-200 text-slate-700 rounded-[1.25rem] font-bold hover:bg-white hover:border-blue-400 hover:text-blue-600 transition-all shadow-md active:scale-95"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  Direct System Print
                </button>
              </div>
            </div>

            {/* Preview Workspace */}
            <div className="flex-1 overflow-auto p-16 flex justify-center items-start scroll-smooth bg-slate-200/50">
              <A4Preview data={examData} />
            </div>
          </div>
        )}
      </main>

      {/* Hidden container specifically for high-fidelity PDF generation */}
      {/* We use a class that keeps it "rendered" but offscreen to avoid html2canvas failures */}
      <div className="pdf-offscreen no-print">
        {examData && (
          <div id="pdf-export-content" className="bg-white">
            <A4Preview data={examData} isExportVersion={true} />
          </div>
        )}
      </div>

      {/* Dedicated System Print container */}
      <div className="print-only-container hidden">
        {examData && <A4Preview data={examData} isExportVersion={true} />}
      </div>

      {appState === AppState.LANDING && (
        <footer className="no-print border-t border-slate-200 py-16 bg-white mt-auto">
          <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row justify-between items-center gap-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-[0.8rem] flex items-center justify-center text-white text-xl font-black">
                P
              </div>
              <span className="font-black text-slate-900 tracking-tight text-2xl">Paper Composer AI</span>
            </div>
            <p className="text-slate-400 font-bold text-sm tracking-wide uppercase">
              Professional Exam Architecture.
            </p>
          </div>
        </footer>
      )}
    </div>
  );
};

export default App;

