/**
 * Helper component to render math formatting like x^2 as x² and H_2O as H₂O
 * without using dangerouslySetInnerHTML where possible, or using a clean parser.
 */
const FormattedMathText: React.FC<{ text: string }> = ({ text }) => {
  if (!text) return null;

  // Regex to find patterns like x^2 or x^{abc} or x_2 or x_{abc}
  // This split keeps the delimiters so we can iterate through them
  const parts = text.split(/(\^\{?[a-zA-Z0-9+-]+\}?|_\{?[a-zA-Z0-9+-]+\}?)/g);

  return (
    <>
      {parts.map((part, index) => {
        if (part.startsWith('^')) {
          // Extract the content: remove ^ and optional {}
          const exponent = part.slice(1).replace(/[\{\}]/g, '');
          return <sup key={index} className="text-[0.75em] leading-none">{exponent}</sup>;
        } else if (part.startsWith('_')) {
          // Extract the content: remove _ and optional {}
          const subscript = part.slice(1).replace(/[\{\}]/g, '');
          return <sub key={index} className="text-[0.75em] leading-none">{subscript}</sub>;
        }
        return <span key={index}>{part}</span>;
      })}
    </>
  );
};

