import { GoogleGenAI, Type } from "@google/genai";

const PROMPT_SYSTEM = `You are a world-class exam paper composer specializing in South Asian educational materials. 
Your task is to transcribe handwritten images into structured digital formats (JSON).

URDU COMPOSITION RULES:
1. You will often see Urdu, Arabic, or Persian scripts mixed with English. Transcribe these exactly as written.
2. Maintain proper punctuation for Urdu (e.g., using '-' as the sentence ending mark if present).
3. Identify school names like "GOVERNMENT HIGH SCHOOL..." and transcribe both the English and Urdu versions if they appear in the header.
4. For questions in Urdu, transcribe the text accurately. If a question contains choices (like 1, 2, 3), represent them clearly.

MATHEMATICAL & SCIENTIFIC FORMATTING:
- Use '^' for powers (e.g., x^2).
- Use '_' for subscripts (e.g., H_2O).

STRUCTURE:
- Capture metadata: Title, Subject, Total Marks, Time Allowed.
- Divide the paper into logical 'sections' (Section A, B, Section Alf, Section Bay, etc.).
- Maintain question numbering (Q.1, Q.2...).
- If a question has parts (a, b, c), put them into 'subQuestions'.

Output MUST be valid JSON according to the schema.`;

const EXAM_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING, description: 'The main institutional header (English and/or Urdu)' },
    subject: { type: Type.STRING, description: 'The subject name' },
    totalMarks: { type: Type.STRING, description: 'Total marks value' },
    timeAllowed: { type: Type.STRING, description: 'Allowed time' },
    sections: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: 'Section title (e.g., SECTION A (سیکشن الف))' },
          instructions: { type: Type.STRING, description: 'Optional section instructions' },
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                number: { type: Type.STRING, description: 'The question number' },
                text: { type: Type.STRING, description: 'The full question text' },
                marks: { type: Type.STRING, description: 'Marks for this question' },
                subQuestions: {
                  type: Type.ARRAY,
                  items: { type: Type.STRING }
                }
              },
              required: ['number', 'text']
            }
          }
        },
        required: ['title', 'questions']
      }
    }
  },
  required: ['title', 'subject', 'sections']
};

export const processHandwrittenImage = async (base64Images: string[]): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts = base64Images.map(img => ({
    inlineData: {
      data: img.split(',')[1],
      mimeType: 'image/jpeg'
    }
  }));

  parts.push({ text: "Please transcribe this exam paper. Pay close attention to the Urdu text and institutional header. Format it professionally for A4 printing." } as any);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: parts as any },
      config: {
        systemInstruction: PROMPT_SYSTEM,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
      }
    });

    if (!response.text) {
      throw new Error("No content generated");
    }

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

