              new Paragraph({
                alignment: AlignmentType.CENTER,
                spacing: { before: 200, after: 200 },
                children: [
                  new TextRun({ 
                    text: `(Instructions: ${section.instructions})`, 
                    italic: true, 
                    size: 20,
                  }),
                ],
              }),
            ] : [new Paragraph({ spacing: { before: 200 } })]),

            ...section.questions.flatMap((q) => {
              return [
                new Paragraph({
                  spacing: { before: 200, after: 100 },
                  children: [
                    new TextRun({ text: `Q.${q.number}\t`, bold: true }),
                    new TextRun({ 
                      text: q.text,
                    }),
                    ...(q.marks ? [new TextRun({ text: `\t[${q.marks}]`, bold: true })] : []),
                  ],
                  tabStops: [
                    { type: AlignmentType.LEFT, position: 720 },
                    { type: AlignmentType.RIGHT, position: 9000 },
                  ],
                }),
                ...(q.subQuestions ? q.subQuestions.map((sub, idx) => {
                  return new Paragraph({
                    indent: { left: 1080 },
                    spacing: { before: 100 },
                    children: [
                      new TextRun({ 
                        text: `(${String.fromCharCode(97 + idx)})  ${sub}`,
                      }),
                    ],
                  });
                }) : []),
              ];
            }),
            new Paragraph({ spacing: { before: 400 } }),
          ]),

          // Footer Marker
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 600 },
