            children: [
              new TextRun({ 
                text: "   *** END OF PAPER ***   ", 
                bold: true, 
                size: 22 
              }),
            ],
          }),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${data.subject.replace(/\s+/g, '_') || "Exam_Paper"}_Professional.docx`;
  a.click();
  window.URL.revokeObjectURL(url);
};

import { GoogleGenAI, Type } from "@google/genai";

const PROMPT_SYSTEM = `You are a world-class professional exam paper composer.
Your task is to take images of handwritten exam papers or notes and convert them into a clean, structured digital JSON format.

RULES:
1. Transcribe the handwriting exactly, fixing only obvious spelling errors or grammar issues if requested by the context.
2. Maintain professional institutional headers (School name, Subject, Total Marks, Time).
3. Identify Sections (e.g., Section A, Section B) and maintain Question numbering (Q.1, Q.2...).
4. Handle mathematical notation using '^' for superscripts (e.g., x^2) and '_' for subscripts (e.g., H_2O).
5. If a question has multiple parts, group them in 'subQuestions'.

Output MUST be a valid JSON object matching the provided schema.`;

const EXAM_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING, description: 'The main institutional header or title' },
    subject: { type: Type.STRING, description: 'The subject name' },
    totalMarks: { type: Type.STRING, description: 'Total marks value' },
    timeAllowed: { type: Type.STRING, description: 'Allowed time' },
    sections: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING, description: 'Section title (e.g., SECTION A)' },
          instructions: { type: Type.STRING, description: 'Section instructions' },
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                number: { type: Type.STRING, description: 'Question number' },
                text: { type: Type.STRING, description: 'Main question text' },
                marks: { type: Type.STRING, description: 'Marks assigned' },
                subQuestions: {
                  type: Type.ARRAY,
                  items: { type: Type.STRING }
                }
              },
              required: ['number', 'text']
            }
          }
        },
        required: ['title', 'questions']
      }
    }
  },
  required: ['title', 'subject', 'sections']
};

export const processHandwrittenImage = async (base64Images: string[]): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts = base64Images.map(img => ({
    inlineData: {
      data: img.split(',')[1],
      mimeType: 'image/jpeg'
    }
  }));

  parts.push({ text: "Transcribe this exam paper professionally. Ensure headers, sections, and questions are clearly separated. Use ^ for mathematical powers." } as any);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: parts as any },
      config: {
        systemInstruction: PROMPT_SYSTEM,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
      }
    });

    if (!response.text) {
      throw new Error("No content generated");
    }

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

