/**
 * Strips common prefixes like "a)", "1.", "(a)", "a." from a string.
 */
const stripOptionLabel = (text: string): string => {
  if (!text) return "";
  // Matches patterns like: a) , (a) , a. , 1) , 1. at the start of string
  return text.replace(/^(\(?[a-zA-Z0-9]\s?[\)\.]\s?)/i, '').trim();
};

/**
 * Strips prefixes like "Q", "Q.", "Question" from question numbers to avoid doubling.
 */
const stripQuestionPrefix = (num: string): string => {
  if (!num) return "";
  return num.replace(/^(Q|Question|Quest|Q\.)\s*\.?\s*/i, '').trim();
};

const FormattedMathText: React.FC<{ text: string }> = ({ text }) => {
  if (!text) return null;
  const parts = text.split(/(\^\{?[a-zA-Z0-9+-]+\}?|_\{?[a-zA-Z0-9+-]+\}?)/g);
  return (
    <>
      {parts.map((part, index) => {
        if (part.startsWith('^')) {
          const exponent = part.slice(1).replace(/[\{\}]/g, '');
          return <sup key={index} className="text-[0.75em] leading-none">{exponent}</sup>;
        } else if (part.startsWith('_')) {
          const subscript = part.slice(1).replace(/[\{\}]/g, '');
          return <sub key={index} className="text-[0.75em] leading-none">{subscript}</sub>;
        }
        return <span key={index}>{part}</span>;
      })}
    </>
  );
};

